TEST(crestRequestTest, setUrlBuildsBaseUrlFromParts) {
  CrestRequest request;
  request.setHost("crest.cern.ch");
  request.setPort("8080");
  request.setPrefix("http");
  request.setUrl("");

  EXPECT_EQ("http://crest.cern.ch:8080", request.getUrl());
}

TEST(crestRequestTest, setUrlOmitsUnsetPort) {
  CrestRequest request;
  request.setHost("crest.cern.ch");
  request.setPrefix("https");
  request.setUrl("");

  EXPECT_EQ("https://crest.cern.ch", request.getUrl());
}

TEST(crestRequestTest, setUrlWithArgumentIsTakenVerbatim) {
  CrestRequest request;
  request.setHost("ignored.cern.ch");
  request.setUrl("https://crest.cern.ch/api-v6.0");

  EXPECT_EQ("https://crest.cern.ch/api-v6.0", request.getUrl());
}

TEST(crestRequestTest, getUrlBuildsBaseUrlWhenUnset) {
  CrestRequest request;
  request.setHost("crest.cern.ch");
  request.setPort("8080");
  request.setPrefix("http");

  EXPECT_EQ("http://crest.cern.ch:8080", request.getUrl());
}

TEST(crestRequestTest, getUrlRejectsUnsetHost) {
  CrestRequest request;

  EXPECT_THROW(request.getUrl(), CrestException);
}
